/* ---- ribbon geometry builder (true flat geometry, no baked shear) ---- */
function ribbonGeom(x0, x1, half, yFn, sat, pale, tail0, tail1) {
  const N = 200, pos = [], col = [], idx = [];
  const cc = new THREE.Color();
  const mid = (x0 + x1) / 2, hw = Math.max(0.001, (x1 - x0) / 2);
  const push = (x, y) => {
    const t = Math.pow(Math.min(1, Math.abs(x - mid) / hw), 0.9);
    cc.copy(pale).lerp(sat, t);
    pos.push(x, y, 0); col.push(cc.r, cc.g, cc.b);
    return pos.length / 3 - 1;
  };
  for (let i = 0; i <= N; i++) {
    const x = x0 + (x1 - x0) * i / N, y = yFn(x);
    push(x, y + half); push(x, y - half);
  }
  for (let i = 0; i < N; i++) {
    const a = 2 * i, b = 2 * i + 1, c2 = 2 * i + 2, d2 = 2 * i + 3;
    idx.push(a, b, c2, b, d2, c2);
  }
  const L = 0.30;
  if (tail0) {
    const y = yFn(x0);
    const a = push(x0 - L, y + half), b = push(x0 - L, y - half), v = push(x0, y);
    idx.push(0, a, v, 1, b, v);
  }
  if (tail1) {
    const y = yFn(x1);
    const a = push(x1 + L, y + half), b = push(x1 + L, y - half), v = push(x1, y);
    idx.push(2 * N, a, v, 2 * N + 1, b, v);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
  g.setIndex(idx);
  g.computeBoundingBox(); g.computeBoundingSphere();
  return g;
}

