<div id="stepTitle" style="font-weight:bold;margin-top:2px"></div>
<div id="stepText" style="color:#333;line-height:1.35"></div>

<div style="margin-top:6px;color:#555;line-height:1.35">
  Hover any base letter to identify it (strand, position, partner). Click for details. Drag to orbit, scroll to zoom.
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ---------------- ELEMENT SPEC (one line per element) ----------------
   sense ribbon        → triangle-strip BufferGeometry (200 segs) + fishtail notched tips, vertex gradient #6a7fc0→#cfd8f0
   antisense ribbon    → same geometry mirrored about y=0, gradient #23bdee→#bfeafb
   mRNA ribbon         → strip geometry, blunt ends, gradient #ec2f8c→#fbd0e4, length driven by slider
   base tick stubs     → PlaneGeometry(0.045,1) scaled/positioned per column, ribbon colour
   H-bond dot columns  → CircleGeometry(0.025) black, 3 per column (DNA–DNA flank/closed sets and mRNA–DNA sets)
   base letters        → addLabel HTML (black for DNA, #ec2f8c for mRNA)
   5'/3' end labels    → addLabel HTML (black on DNA, magenta on mRNA)
   captions + leaders  → addLabel HTML + Line (black) + triangle head Mesh
   hover pickers       → PlaneGeometry(0.42,0.30), opacity 0, registerInteractive
   hover highlight     → LineLoop rectangle (orange)
   T→U outlines        → LineLoop rectangles (magenta), 'Sense vs mRNA' view
   sense↔mRNA links    → vertical Line segments (grey), 'Sense vs mRNA' view
---------------------------------------------------------------------- */

const G = new THREE.Group();
scene.add(G);

/* ---- palette ---- */
const SENSE_SAT = new THREE.Color(0x6a7fc0), SENSE_PALE = new THREE.Color(0xcfd8f0);
const ANTI_SAT  = new THREE.Color(0x23bdee), ANTI_PALE  = new THREE.Color(0xbfeafb);
const MRNA_SAT  = new THREE.Color(0xec2f8c), MRNA_PALE  = new THREE.Color(0xfbd0e4);
const MAGENTA = '#ec2f8c';

/* ---- layout constants (world units, derived from source proportions) ---- */
const DX = 0.45;                       // base-column spacing
const HALF_DNA = 0.125, HALF_RNA = 0.115;
const Y_SENSE_FLANK = 0.72, Y_SENSE_BUB = 1.32;
const Y_SENSE_LET_C = 0.30, Y_SENSE_LET_O = 0.72;    // closed / bubble-open letter rows
const Y_ANTI_LET_C  = -0.30, Y_ANTI_LET_O = -0.93;
const Y_MRNA = -0.03, Y_MRNA_LET = -0.53;
const DNA_DOT_Y = [0.14, 0.0, -0.14];
const RNA_DOT_Y = [-0.63, -0.73, -0.83];
const XL = -4.275, BENDW = 0.24;
const X0 = -6.42, X1 = 6.42;            // ribbon body (notched tips add 0.13 each side)
const MRNA_X0 = -4.30;
const TIP_L = 0.13;

const SENSE_SEQ = 'TCAGCTGGCTGAACGCGTT';
const MRNA_SEQ  = 'UCAGCUGGCUGAACGCGUU';
const ANTI_SEQ  = 'AGTCGACCGACTTGCGCAA';
const TU_IDX = [0, 5, 9, 17, 18];

let xRcur = XL + DX * 19;
let openAmp = 1;

function smoothstep(a, b, x) {
  const t = Math.min(1, Math.max(0, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
}
function bumpAt(x) {
  if (openAmp <= 0.001) return 0;
  return openAmp * smoothstep(XL - BENDW, XL + BENDW, x) *
         (1 - smoothstep(xRcur - BENDW, xRcur + BENDW, x));
}
function senseY(x) { return Y_SENSE_FLANK + (Y_SENSE_BUB - Y_SENSE_FLANK) * bumpAt(x); }
function antiY(x)  { return -senseY(x); }

/* ---- ribbon geometry builder (true flat geometry in XY, no baked shear) ---- */
function ribbonGeom(x0, x1, half, yFn, sat, pale, tail0, tail1) {
  const N = 220, pos = [], col = [], idx = [];
  const cc = new THREE.Color();
  const mid = (x0 + x1) / 2, hw = Math.max(0.001, (x1 - x0) / 2);
  const push = (x, y) => {
    const t = Math.pow(Math.min(1, Math.abs(x - mid) / hw), 1.2);
    cc.copy(pale).lerp(sat, t);
    pos.push(x, y, 0); col.push(cc.r, cc.g, cc.b);
    return pos.length / 3 - 1;
  };
  for (let i = 0; i <= N; i++) {
    const x = x0 + (x1 - x0) * i / N, y = yFn(x);
    push(x, y + half); push(x, y - half);
  }
  for (let i = 0; i < N; i++) {
    const a = 2 * i, b = 2 * i + 1, c2 = 2 * i + 2, d2 = 2 * i + 3;
    idx.push(a, b, c2, b, d2, c2);
  }
  if (tail0) {
    const y = yFn(x0);
    const a = push(x0 - TIP_L, y + half), b = push(x0 - TIP_L, y - half), v = push(x0, y);
    idx.push(0, a, v, 1, b, v);
  }
  if (tail1) {
    const y = yFn(x1);
    const a = push(x1 + TIP_L, y + half), b = push(x1 + TIP_L, y - half), v = push(x1, y);
    idx.push(2 * N, a, v, 2 * N + 1, b, v);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
  g.setIndex(idx);
  g.computeBoundingBox(); g.computeBoundingSphere();
  return g;
}

const senseMesh = new THREE.Mesh(new THREE.BufferGeometry(),
  new THREE.MeshBasicMaterial({ vertexColors: true, side: THREE.DoubleSide }));
const antiMesh = new THREE.Mesh(new THREE.BufferGeometry(),
  new THREE.MeshBasicMaterial({ vertexColors: true, side: THREE.DoubleSide }));
const mrnaMat = new THREE.MeshBasicMaterial({ vertexColors: true, side: THREE.DoubleSide, transparent: true, opacity: 1 });
const mrnaMesh = new THREE.Mesh(new THREE.BufferGeometry(), mrnaMat);
G.add(senseMesh, antiMesh, mrnaMesh);

function setGeom(mesh, g) { mesh.geometry.dispose(); mesh.geometry = g; }
function rebuildRibbons() {
  setGeom(senseMesh, ribbonGeom(X0, X1, HALF_DNA, senseY, SENSE_SAT, SENSE_PALE, true, true));
  setGeom(antiMesh,  ribbonGeom(X0, X1, HALF_DNA, antiY,  ANTI_SAT,  ANTI_PALE,  true, true));
  const mEnd = MRNA_X0 + Math.max(0, posCur) * DX + 0.05;
  if (posCur > 0.06) {
    mrnaMesh.visible = true;
    setGeom(mrnaMesh, ribbonGeom(MRNA_X0, mEnd, HALF_RNA, () => Y_MRNA, MRNA_SAT, MRNA_PALE, false, false));
  } else mrnaMesh.visible = false;
  return mEnd;
}

/* ---- shared small geometries ---- */
const tickGeo = new THREE.PlaneGeometry(0.045, 1);
const dotGeo  = new THREE.CircleGeometry(0.025, 12);
const unitRect = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(-0.5, -0.5, 0), new THREE.Vector3(0.5, -0.5, 0),
  new THREE.Vector3(0.5, 0.5, 0), new THREE.Vector3(-0.5, 0.5, 0)
]);
const unitVLine = new THREE.BufferGeometry().setFromPoints([
  new THREE.Vector3(0, -0.5, 0), new THREE.Vector3(0, 0.5, 0)
]);

/* ---- columns: 3 flank + 19 bubble + 3 flank ---- */
const cols = [];
function addCol(x, kind, sCh, aCh, i, mCh) { cols.push({ x, kind, sCh, aCh, i, mCh }); }
['C', 'A', 'T'].forEach((ch, k) => addCol(-5.80 + k * DX, 'flank', ch, 'GTA'[k], -1, null));
for (let i = 0; i < 19; i++) addCol(-4.05 + i * DX, 'bubble', SENSE_SEQ[i], ANTI_SEQ[i], i, MRNA_SEQ[i]);
['G', 'A', 'C'].forEach((ch, k) => addCol(4.90 + k * DX, 'flank', ch, 'CTG'[k], -1, null));

const pickMeshes = [];
const LETSIZE = '13px';

cols.forEach((c, ci) => {
  c.key = ci;
  /* letters */
  c.senseLab = addLabel(c.sCh, new THREE.Vector3(c.x, Y_SENSE_LET_C, 0), { fontSize: LETSIZE, color: '#000' });
  c.antiLab  = addLabel(c.aCh, new THREE.Vector3(c.x, Y_ANTI_LET_C, 0),  { fontSize: LETSIZE, color: '#000' });

  /* ticks */
  c.senseTick = new THREE.Mesh(tickGeo, new THREE.MeshBasicMaterial({ color: SENSE_SAT }));
  c.antiTick  = new THREE.Mesh(tickGeo, new THREE.MeshBasicMaterial({ color: ANTI_SAT }));
  G.add(c.senseTick, c.antiTick);

  /* DNA–DNA hydrogen-bond dots (drawn wherever the duplex is closed) */
  c.dnaDotMat = new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true, opacity: 1 });
  c.dnaDots = DNA_DOT_Y.map(y => {
    const m = new THREE.Mesh(dotGeo, c.dnaDotMat);
    m.position.set(c.x, y, 0.02); G.add(m); return m;
  });

  if (c.kind === 'bubble') {
    c.mrnaLab = addLabel(c.mCh, new THREE.Vector3(c.x, Y_MRNA_LET, 0), { fontSize: LETSIZE, color: MAGENTA });
    c.mrnaTickMat = new THREE.MeshBasicMaterial({ color: MRNA_SAT, transparent: true, opacity: 1 });
    c.mrnaTick = new THREE.Mesh(tickGeo, c.mrnaTickMat);
    c.mrnaTick.scale.y = 0.22;
    c.mrnaTick.position.set(c.x, Y_MRNA - HALF_RNA - 0.11, 0);
    G.add(c.mrnaTick);

    c.rnaDotMat = new THREE.MeshBasicMaterial({ color: 0x000000, transparent: true, opacity: 1 });
    c.rnaDots = RNA_DOT_Y.map(y => {
      const m = new THREE.Mesh(dotGeo, c.rnaDotMat);
      m.position.set(c.x, y, 0.02); G.add(m); return m;
    });

    /* sense <-> mRNA connector (Sense vs mRNA view) */
    c.link = new THREE.Line(unitVLine, new THREE.LineBasicMaterial({ color: 0xbcbcbc, transparent: true, opacity: 0.9 }));
    c.link.visible = false; G.add(c.link);

    if (TU_IDX.indexOf(c.i) >= 0) {
      const mk = () => {
        const l = new THREE.LineLoop(unitRect, new THREE.LineBasicMaterial({ color: MRNA_SAT }));
        l.scale.set(0.28, 0.25, 1); l.visible = false; G.add(l); return l;
      };
      c.boxSense = mk(); c.boxMrna = mk();
      c.boxMrna.position.set(c.x, Y_MRNA_LET, 0.03);
    }
  }

  /* hover pickers */
  const mkPick = (strand, y, info) => {
    const p = new THREE.Mesh(new THREE.PlaneGeometry(0.42, 0.30),
      new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false }));
    p.position.set(c.x, y, 0.1);
    p.userData.key = strand + ':' + ci;
    G.add(p); pickMeshes.push(p);
    registerInteractive(p, info);
    return p;
  };
  const pos = c.kind === 'bubble' ? (c.i + 1) : null;
  c.pickSense = mkPick('s', Y_SENSE_LET_C, {
    title: 'Sense (coding) strand — ' + c.sCh,
    tooltip: 'Sense strand ' + c.sCh + (pos ? ' · bubble position ' + pos : ' · paired flank'),
    body: 'DNA sense strand, read 5\u2032\u21923\u2032 left to right. Base ' + c.sCh +
      ' pairs with ' + c.aCh + ' on the antisense (template) strand.' +
      (c.mCh ? ' The transcript carries ' + c.mCh + ' here — identical to the sense base except T is replaced by U.' :
        ' This position lies outside the transcription bubble, so the duplex stays closed.')
  });
  c.pickAnti = mkPick('a', Y_ANTI_LET_C, {
    title: 'Antisense (template) strand — ' + c.aCh,
    tooltip: 'Antisense/template ' + c.aCh + (pos ? ' · bubble position ' + pos : ' · paired flank'),
    body: 'DNA antisense strand, running 3\u2032\u21925\u2032 left to right — this is the strand RNA polymerase reads.' +
      ' Template base ' + c.aCh + (c.mCh ? ' specifies ribonucleotide ' + c.mCh + ' in the mRNA.' : ' is hydrogen bonded to sense base ' + c.sCh + '.')
  });
  if (c.kind === 'bubble') {
    c.pickMrna = mkPick('m', Y_MRNA_LET, {
      title: 'mRNA nucleotide — ' + c.mCh,
      tooltip: 'mRNA ' + c.mCh + ' · nucleotide ' + pos,
      body: 'mRNA nucleotide ' + pos + ' of 19, synthesized 5\u2032\u21923\u2032. It is complementary to template base ' +
        c.aCh + ' and therefore matches sense base ' + c.sCh + ' (with U in place of T).'
    });
  }
});

/* ---- 5'/3' end labels ---- */
const ENDSIZE = '13px';
addLabel('5\u2032', new THREE.Vector3(-6.86, Y_SENSE_FLANK, 0), { fontSize: ENDSIZE, color: '#000' });
addLabel('3\u2032', new THREE.Vector3(6.86, Y_SENSE_FLANK, 0), { fontSize: ENDSIZE, color: '#000' });
addLabel('3\u2032', new THREE.Vector3(-6.86, -Y_SENSE_FLANK, 0), { fontSize: ENDSIZE, color: '#000' });
addLabel('5\u2032', new THREE.Vector3(6.86, -Y_SENSE_FLANK, 0), { fontSize: ENDSIZE, color: '#000' });
const lab5Mrna = addLabel('5\u2032', new THREE.Vector3(MRNA_X0 - 0.26, Y_MRNA, 0), { fontSize: ENDSIZE, color: MAGENTA });
const lab3Mrna = addLabel('3\u2032', new THREE.Vector3(4.55, Y_MRNA, 0), { fontSize: ENDSIZE, color: MAGENTA });

/* ---- captions with leader arrows ---- */
function leader(fx, fy, tx, ty) {
  const line = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(fx, fy, 0.05), new THREE.Vector3(tx, ty, 0.05)]),
    new THREE.LineBasicMaterial({ color: 0x000000 }));
  G.add(line);
  const ang = Math.atan2(ty - fy, tx - fx), hl = 0.15, hw = 0.055;
  const bx = tx - Math.cos(ang) * hl, by = ty - Math.sin(ang) * hl;
  const px = -Math.sin(ang) * hw, py = Math.cos(ang) * hw;
  const hg = new THREE.BufferGeometry();
  hg.setAttribute('position', new THREE.Float32BufferAttribute(
    [tx, ty, 0.05, bx + px, by + py, 0.05, bx - px, by - py, 0.05], 3));
  G.add(new THREE.Mesh(hg, new THREE.MeshBasicMaterial({ color: 0x000000, side: THREE.DoubleSide })));
}
addLabel('DNA sense<br>strand', new THREE.Vector3(-5.10, 1.72, 0), { fontSize: '13px', color: '#000' });
leader(-4.92, 1.42, -4.40, 0.98);
addLabel('DNA antisense<br>strand', new THREE.Vector3(-4.80, -1.80, 0), { fontSize: '13px', color: '#000' });
leader(-4.62, -1.52, -4.15, -1.15);
addLabel('mRNA', new THREE.Vector3(5.66, -1.56, 0), { fontSize: '13px', color: '#000' });
leader(5.30, -1.36, 4.44, -0.21);

/* ---- hover highlight box ---- */
const hlBox = new THREE.LineLoop(unitRect, new THREE.LineBasicMaterial({ color: 0xff8c00 }));
hlBox.scale.set(0.32, 0.27, 1);
hlBox.position.z = 0.12;
hlBox.visible = false;
G.add(hlBox);

/* ---------------- state + update ---------------- */
let posTarget = 19, posCur = 19, needsUpdate = true;
let pairingView = 'dr';          // 'dd' | 'dr' | 'sm'
let hoverStrand = null, hoverCol = -1;

function update() {
  const p = posCur;
  openAmp = smoothstep(0, 0.5, p);
  xRcur = XL + DX * Math.max(0, p);
  const mEnd = rebuildRibbons();

  const isDD = pairingView === 'dd';
  const isDR = pairingView === 'dr';
  const isSM = pairingView === 'sm';
  const eRna = isDR ? 1 : 0.32;
  const eMrRibbon = isDD ? 0.5 : 1;
  const eMrLetter = isDD ? 0.6 : 1;
  const dnaDotScale = isDD ? 1.45 : 1.0;
  mrnaMat.opacity = eMrRibbon;

  for (const c of cols) {
    const t = c.kind === 'bubble' ? bumpAt(c.x) : 0;
    const m = c.kind === 'bubble' ? THREE.MathUtils.clamp(p - c.i, 0, 1) : 0;
    const mv = THREE.MathUtils.clamp((m - 0.2) / 0.5, 0, 1);
    const dim = (hoverCol >= 0 && hoverCol !== c.key) ? 0.25 : 1;

    const sy = THREE.MathUtils.lerp(Y_SENSE_LET_C, Y_SENSE_LET_O, t);
    const ay = THREE.MathUtils.lerp(Y_ANTI_LET_C, Y_ANTI_LET_O, t);
    c.senseLab.pos.y = sy; c.antiLab.pos.y = ay;
    c.senseLab.div.style.opacity = dim;
    c.antiLab.div.style.opacity = dim;

    /* tick stubs point inward from each ribbon toward its letter row */
    const sBot = senseY(c.x) - HALF_DNA, sLen = THREE.MathUtils.lerp(0.18, 0.26, t);
    c.senseTick.position.set(c.x, sBot - sLen / 2, 0);
    c.senseTick.scale.y = sLen;
    const aTop = antiY(c.x) + HALF_DNA, aLen = THREE.MathUtils.lerp(0.18, 0.13, t);
    c.antiTick.position.set(c.x, aTop + aLen / 2, 0);
    c.antiTick.scale.y = aLen;

    /* DNA–DNA dots: present wherever the duplex is still closed */
    const closed = c.kind === 'bubble' ? (1 - t) : 1;
    c.dnaDotMat.opacity = closed * dim;
    c.dnaDots.forEach(dt => { dt.visible = closed > 0.05; dt.scale.setScalar(dnaDotScale); });

    c.pickSense.position.y = sy;
    c.pickAnti.position.y = ay;

    if (c.kind === 'bubble') {
      c.mrnaLab.div.style.opacity = mv * dim * eMrLetter;
      c.mrnaTickMat.opacity = mv * eMrRibbon;
      c.mrnaTick.visible = mv > 0.02;
      c.rnaDotMat.opacity = eRna * mv * dim;
      c.rnaDots.forEach(dt => { dt.visible = mv > 0.02; dt.scale.setScalar(isDR ? 1.3 : 1); });
      c.pickMrna.visible = mv > 0.5;

      const showLink = isSM && mv > 0.6;
      c.link.visible = showLink;
      if (showLink) {
        const top = sy - 0.13, bot = Y_MRNA_LET + 0.13;
        c.link.position.set(c.x, (top + bot) / 2, 0.01);
        c.link.scale.y = Math.max(0.01, top - bot);
      }
      if (c.boxSense) {
        c.boxSense.visible = showLink;
        c.boxMrna.visible = showLink;
        c.boxSense.position.set(c.x, sy, 0.03);
      }
    }
  }

  /* mRNA end labels track the growing 3' end */
  const mVis = posCur > 0.15 ? 1 : 0;
  lab5Mrna.div.style.opacity = mVis * eMrLetter;
  lab3Mrna.div.style.opacity = mVis * eMrLetter;
  lab3Mrna.pos.x = mEnd + 0.25;
  lab3Mrna.pos.y = Y_MRNA;

  /* hover highlight */
  if (hoverCol >= 0 && hoverStrand) {
    const c = cols[hoverCol];
    const t = c.kind === 'bubble' ? bumpAt(c.x) : 0;
    let y = THREE.MathUtils.lerp(Y_SENSE_LET_C, Y_SENSE_LET_O, t);
    if (hoverStrand === 'a') y = THREE.MathUtils.lerp(Y_ANTI_LET_C, Y_ANTI_LET_O, t);
    if (hoverStrand === 'm') y = Y_MRNA_LET;
    hlBox.position.set(c.x, y, 0.12);
    hlBox.visible = true;
  } else hlBox.visible = false;
}

/* first build, then camera, per ordering rules */
update();
setCameraView({ projection: 'orthographic', axisScreenAngles: null, heightFraction: 0.86 });

/* ---------------- animation loop for eased slider ---------------- */
function tickLoop() {
  requestAnimationFrame(tickLoop);
  if (Math.abs(posCur - posTarget) > 0.004) { posCur += (posTarget - posCur) * 0.11; needsUpdate = true; }
  else if (posCur !== posTarget) { posCur = posTarget; needsUpdate = true; }
  if (needsUpdate) { needsUpdate = false; update(); }
}
tickLoop();

/* ---------------- hover picking ---------------- */
const hRay = new THREE.Raycaster(), hPtr = new THREE.Vector2();
canvas.addEventListener('pointermove', (e) => {
  const r = canvas.getBoundingClientRect();
  hPtr.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  hPtr.y = -((e.clientY - r.top) / r.height) * 2 + 1;
  hRay.setFromCamera(hPtr, camera);
  const hits = hRay.intersectObjects(pickMeshes, false);
  let s = null, k = -1;
  if (hits.length) {
    const parts = hits[0].object.userData.key.split(':');
    s = parts[0]; k = parseInt(parts[1], 10);
  }
  if (s !== hoverStrand || k !== hoverCol) { hoverStrand = s; hoverCol = k; needsUpdate = true; }
});
canvas.addEventListener('pointerleave', () => {
  if (hoverCol >= 0) { hoverCol = -1; hoverStrand = null; needsUpdate = true; }
});

/* ---------------- UI wiring ---------------- */
const slider = document.getElementById('posSlider');
const posVal = document.getElementById('posVal');
slider.addEventListener('input', () => {
  posTarget = parseFloat(slider.value);
  posVal.textContent = slider.value;
  needsUpdate = true;
  stopPlay();
});

const pvBtns = { dd: document.getElementById('pvDD'), dr: document.getElementById('pvDR'), sm: document.getElementById('pvSM') };
const pvNote = document.getElementById('pvNote');
const PV_TEXT = {
  dd: 'Closed-duplex dot columns are enlarged: A pairs with T, G pairs with C.',
  dr: 'Hydrogen bonds between the template (antisense) DNA and the new RNA are emphasized: A pairs with U.',
  sm: 'Grey links compare sense DNA with the transcript; magenta boxes mark every T\u2192U substitution.'
};
function setPairing(v) {
  pairingView = v;
  for (const k in pvBtns) pvBtns[k].classList.toggle('active', k === v);
  pvNote.textContent = PV_TEXT[v];
  needsUpdate = true;
}
pvBtns.dd.addEventListener('click', () => { setPairing('dd'); stopPlay(); });
pvBtns.dr.addEventListener('click', () => { setPairing('dr'); stopPlay(); });
pvBtns.sm.addEventListener('click', () => { setPairing('sm'); stopPlay(); });
setPairing('dr');

/* ---------------- guided demo ---------------- */
const STEPS = [
  { title: '1 · Closed duplex', pos: 0, pv: 'dd',
    text: 'Before transcription the sense (blue-violet) and antisense (cyan) strands are paired end to end; note the antiparallel 5\u2032\u21923\u2032 labels and the dot columns marking hydrogen bonds.' },
  { title: '2 · Bubble opens, RNA begins', pos: 5, pv: 'dr',
    text: 'The strands bow apart and RNA polymerase reads the antisense strand 3\u2032\u21925\u2032, laying down the first ribonucleotides: template A gives U, G gives C, T gives A.' },
  { title: '3 · Transcript elongates', pos: 12, pv: 'dr',
    text: 'The bubble advances; behind it the DNA would reclose, while ahead new template bases are exposed. The magenta strand grows only at its 3\u2032 end.' },
  { title: '4 · Full transcript', pos: 19, pv: 'dr',
    text: 'All 19 template bases have been read. The mRNA reads 5\u2032-UCAGCUGGCUGAACGCGUU-3\u2032.' },
  { title: '5 · Sense strand vs mRNA', pos: 19, pv: 'sm',
    text: 'Compare upward: the mRNA matches the sense strand base for base, except every T is replaced by U \u2014 which is why the sense strand is also called the coding strand.' }
];
let stepIdx = 3;
const stepTitle = document.getElementById('stepTitle');
const stepText = document.getElementById('stepText');
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  posTarget = s.pos;
  slider.value = String(s.pos);
  posVal.textContent = String(s.pos);
  setPairing(s.pv);
  stepTitle.textContent = s.title;
  stepText.textContent = s.text;
  needsUpdate = true;
}
document.getElementById('btnPrev').addEventListener('click', () => { stopPlay(); goToStep(stepIdx - 1); });
document.getElementById('btnNext').addEventListener('click', () => { stopPlay(); goToStep(stepIdx + 1); });

let playTimer = null;
const btnPlay = document.getElementById('btnPlay');
function stopPlay() {
  if (playTimer) { clearInterval(playTimer); playTimer = null; btnPlay.textContent = '\u25B6 Play'; btnPlay.classList.remove('active'); }
}
btnPlay.addEventListener('click', () => {
  if (playTimer) { stopPlay(); return; }
  btnPlay.textContent = '\u275A\u275A Pause';
  btnPlay.classList.add('active');
  goToStep(0);
  playTimer = setInterval(() => {
    if (stepIdx === STEPS.length - 1) { stopPlay(); return; }
    goToStep(stepIdx + 1);
  }, 3600);
});

goToStep(3);
